import { useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useProjectsContext } from './projects-context.js';
import { addTask, editTask, removeTask, toggleTask, taskProgress } from './task-tree.js';
import { areaSections, findTask } from './task-views.js';
import { ProgressRing } from './progress-ring.js';
import { ProgressBar } from './progress-bar.js';
import { CheckRow } from './check-row.js';
import { TaskForm } from './task-form.js';
import { NotFound } from './project-overview-page.js';
import styles from './ui.module.css';

/**
 * Area focus frame: one area of a project (e.g. "Gun system").
 * Its tasks are shown as flat sections — direct tasks, then one section per
 * sub-group — so there is never more than one level to read through.
 */
export function AreaPage() {
  const { projectId, areaId } = useParams();
  const { projects, loading, updateTasks } = useProjectsContext();
  const [adding, setAdding] = useState<string | null>(null);
  const [editingArea, setEditingArea] = useState(false);
  const project = projects.find((p) => p.id === projectId);
  const area = project && areaId ? findTask(project.tasks, areaId) : undefined;

  if (loading) return <p className={styles.empty}>Loading…</p>;
  if (!project || !area) return <NotFound />;

  const p = taskProgress(area);
  const sections = areaSections(area);
  const update = (fn: Parameters<typeof updateTasks>[1]) => updateTasks(project.id, fn);
  const groupTitle = (title: string) => (title === 'General' || title === 'Tasks' ? null : title);

  return (
    <div className={styles.page}>
      <header className={styles.projectHead}>
        <nav className={styles.breadcrumb} aria-label="Breadcrumb">
          <Link to="/">Dashboard</Link> <span>›</span>
          <Link to={`/projects/${project.id}`}>{project.name}</Link> <span>›</span>
          <span>{area.title}</span>
        </nav>
        {editingArea ? (
          <TaskForm initial={area} submitLabel="Save" onCancel={() => setEditingArea(false)} onSubmit={(v) => { update((t) => editTask(t, area.id, v)); setEditingArea(false); }} />
        ) : (
          <div className={styles.focusHead}>
            <ProgressRing percent={p.percent} color={project.color} size={88} />
            <div className={styles.focusInfo}>
              <h1 className={styles.pageTitle}>{area.title}</h1>
              {area.description ? <p className={styles.muted}>{area.description}</p> : null}
              <p className={styles.muted}><strong className={styles.strong}>{p.done}</strong> of {p.total} tasks done</p>
            </div>
            <button className={styles.ghostBtn} onClick={() => setEditingArea(true)}>Edit</button>
          </div>
        )}
      </header>

      {sections.map((s) => {
        const title = groupTitle(s.title);
        return (
          <section key={s.id} className={styles.card}>
            <div className={styles.groupHead}>
              <h2 className={styles.groupTitle}>{s.title}</h2>
              <span className={styles.groupPct}>{s.done}/{s.total} · {s.percent}%</span>
            </div>
            {s.description ? <p className={styles.groupDesc}>{s.description}</p> : null}
            <ProgressBar percent={s.percent} color={project.color} />
            <ul className={styles.checkList}>
              {s.items.map((i) => (
                <CheckRow
                  key={i.task.id}
                  task={i.task}
                  path={i.path}
                  color={project.color}
                  onToggle={() => update((t) => toggleTask(t, i.task.id))}
                  onEdit={(v) => update((t) => editTask(t, i.task.id, v))}
                  onRemove={() => update((t) => removeTask(t, i.task.id))}
                />
              ))}
            </ul>
            <div className={styles.sectionFoot}>
              {adding === s.id ? (
                <TaskForm
                  placeholder={title ? `New task in ${title}` : 'New task'}
                  onCancel={() => setAdding(null)}
                  onSubmit={(v) => update((t) => addTask(t, title ? s.id : area.id, v))}
                />
              ) : (
                <div className={styles.footActions}>
                  <button className={styles.linkBtn} onClick={() => setAdding(s.id)}>+ Add task</button>
                  {title ? (
                    <button className={styles.dangerLink} onClick={() => window.confirm(`Delete group "${title}"?`) && update((t) => removeTask(t, s.id))}>
                      Delete group
                    </button>
                  ) : null}
                </div>
              )}
            </div>
          </section>
        );
      })}

      <section className={`${styles.card} ${styles.cardDashed}`}>
        {adding === 'new-group' ? (
          <TaskForm
            placeholder="Group name, e.g. Server side"
            submitLabel="Add group"
            onCancel={() => setAdding(null)}
            onSubmit={(v) => {
              // a group is a task that holds tasks; seed it with a first placeholder task
              update((t) => {
                const withGroup = addTask(t, area.id, v);
                const group = findTask(withGroup, area.id)!.subtasks.at(-1)!;
                return addTask(withGroup, group.id, { title: 'First task' });
              });
              setAdding(null);
            }}
          />
        ) : (
          <div className={styles.footActions}>
            {!sections.length ? (
              <button className={styles.primaryBtn} onClick={() => setAdding(sections[0]?.id || `${area.id}-direct`)}>+ Add first task</button>
            ) : null}
            <button className={styles.linkBtn} onClick={() => setAdding('new-group')}>+ New group of tasks</button>
          </div>
        )}
        {!sections.length && adding === `${area.id}-direct` ? (
          <TaskForm placeholder="New task" onCancel={() => setAdding(null)} onSubmit={(v) => update((t) => addTask(t, area.id, v))} />
        ) : null}
      </section>
    </div>
  );
}
